  "metadata": {
    "productName": "ThumbnailSafi",
    "version": "1.0.0",
    "lastUpdated": "2024-05-22",
    "status": "Production Ready",
    "description": "A specialized generative AI application for creating, editing, and managing high-CTR YouTube thumbnails."
  },
  "overview": {
    "problemStatement": "Content creators struggle to produce high-quality, click-worthy thumbnails quickly. Existing tools are either too complex (Photoshop) or generic (standard AI image generators) without understanding YouTube-specific composition and typography needs.",
    "solution": "A streamlined, batch-processing AI tool that specifically targets 16:9 compositions, readable typography, and distinct visual styles popular on YouTube. It integrates generation, editing, and SEO metadata creation into one flow.",
    "keyValuePropositions": [
      "Batch generation for A/B testing concepts.",
      "YouTube-specific style presets (e.g., 'React Face', 'Tech Anime').",
      "Integrated Image-to-Image editing workflow.",
      "Automatic SEO metadata generation (Title, Description, Tags)."
    ]
  },
  "targetAudience": [
    "YouTube Content Creators",
    "Social Media Managers",
    "Digital Marketers",
    "Streamers"
  ],
  "functionalRequirements": {
    "inputAndConfiguration": {
      "textPrompting": {
        "description": "Users can input natural language prompts describing the desired thumbnail.",
        "features": [
          "Random prompt generator",
          "Preset prompt library based on selected style"
        ]
      },
      "imageInput": {
        "description": "Users can upload reference images or selfies to be used as the basis for generation.",
        "features": [
          "Drag and drop support",
          "Built-in cropping tool to enforce 16:9 aspect ratio",
          "AI Analysis: 'Analyze Image' button to generate a prompt from the uploaded image"
        ]
      },
      "styleSelection": {
        "description": "Pre-defined visual styles optimized for YouTube.",
        "modes": [
          "Default (High impact, expressive faces)",
          "Tech Anime (Vector art, neon)",
          "Cinematic (Photorealistic, professional)",
          "Minimalist (Clean, negative space)",
          "Bold Typography (Text-heavy)",
          "Vibrant (High saturation, gaming)"
        ]
      },
      "layoutControl": {
        "description": "Explicit control over composition structure.",
        "options": [
          "Subject Left / Text Right",
          "Subject Right / Text Left",
          "Split Screen",
          "Text Overlay",
          "Minimalist Corner"
        ]
      },
      "modelSelection": {
        "description": "Selection between different underlying AI models.",
        "options": [
          "Imagen 4.0 (High fidelity image generation)",
          "Gemini Image Editor (For image-to-image and editing tasks)"
        ]
      },
      "batchControl": {
        "description": "Slider to control number of variations generated simultaneously (1-6)."
      }
    },
    "generationAndOutput": {
      "coreGeneration": {
        "description": "Asynchronous generation of images based on inputs.",
        "mechanics": "Utilizes Google GenAI SDK. Routes text-to-image to Imagen and image-to-image to Gemini Flash."
      },
      "metadataGeneration": {
        "description": "Concurrent generation of text metadata.",
        "outputs": [
          "SEO-optimized Title",
          "Video Description",
          "Hashtags and Tags"
        ]
      },
      "feedInterface": {
        "description": "Reverse-chronological feed of generation 'rounds'.",
        "features": [
          "Flip-card animation for outputs",
          "Quick re-run/duplicate prompt buttons",
          "Download all as ZIP"
        ]
      }
    },
    "editingAndRefining": {
      "quickEdits": {
        "description": "One-click prompt modifiers.",
        "options": [
          "Change background",
          "Remove object",
          "Add object",
          "Change expression"
        ]
      },
      "deepEditor": {
        "description": "Modal for conversational editing of a specific output.",
        "capabilities": "Users can chat with the AI to refine a specific generated image (e.g., 'Make the text yellow')."
      }
    },
    "historyAndPersistence": {
      "sessionHistory": {
        "description": "Local storage of successful generations.",
        "features": [
          "View past generations",
          "Restore generation to feed",
          "Delete specific items",
          "Clear all history"
        ]
      }
    }
  },
  "uiUxRequirements": {
    "theme": {
      "description": "System-aware Light/Dark mode toggle."
    },
    "responsiveness": {
      "description": "Mobile-first controls with touch-optimized selectors and fullscreen viewers."
    },
    "feedback": {
      "description": "Real-time timers for generation duration, loading spinners, and toast notifications for clipboard actions."
    }
  },
  "technicalArchitecture": {
    "frontend": {
      "framework": "React 18",
      "stateManagement": "Zustand (with Immer & Persist middleware)",
      "styling": "CSS Modules + Global Variables",
      "bundling": "ES Modules via HTML importmap (No build step required for dev)"
    },
    "backendRoutes": {
      "api/generate": {
        "method": "POST",
        "logic": "Handles retry logic. Routes 'Imagen' models to `ai.models.generateImages` and 'Gemini' models to `ai.models.generateContent` with `responseModalities: ['IMAGE']`."
      },
      "api/generate_caption": {
        "method": "POST",
        "logic": "Uses `gemini-2.5-flash` to generate text metadata."
      },
      "api/analyze_image": {
        "method": "POST",
        "logic": "Uses multimodal `gemini-2.5-flash` to describe an uploaded image for prompting."
      }
    },
    "externalServices": {
      "sdk": "@google/genai",
      "imageProcessing": "react-image-crop",
      "utilities": "jszip (client-side zipping)"
    }
  },
  "dataDictionary": {
    "Round": {
      "id": "UUID",
      "prompt": "String",
      "uploadedImage": "Base64 String (Optional)",
      "outputs": "Array[Output]",
      "layout": "String",
      "outputMode": "String"
    },
    "Output": {
      "id": "UUID",
      "outputData": "Base64 String (Image)",
      "caption": "Object { title, description, tags }",
      "stats": "{ startTime, totalTime }"
    }
  }
}

{
  "guideTitle": "Visually Appealing Design Principles for App-Processed Thumbnails",
  "guideDescription": "A compelling thumbnail should grab attention, spark curiosity, and accurately represent the video's content. This guide outlines principles for the app to process and suggest effective thumbnail design elements based on user input or content analysis.",
  "sections": [
    {
      "sectionTitle": "Aesthetic and Color Strategy",
      "principles": [
        {
          "name": "Bold, Contrasting Colors",
          "instruction": "Prioritize high-contrast, vibrant color combinations (e.g., yellow/black, blue/orange) to ensure the thumbnail stands out. **Avoid** palettes that blend with common interface backgrounds (white, black/red themes).",
          "keywords": ["vibrant", "high-contrast", "stand out"]
        },
        {
          "name": "Maintain Brand Consistency",
          "instruction": "Apply a consistent color palette, font, and layout style based on the user's established 'brand' to build recognition and a professional channel look.",
          "keywords": ["consistency", "branding", "palette"]
        }
      ]
    },
    {
      "sectionTitle": "Composition and Visual Focus",
      "principles": [
        {
          "name": "Incorporate Expressive Faces",
          "instruction": "Recommend or automatically crop/highlight close-up shots of people displaying strong emotions (surprise, excitement, curiosity) as they tend to generate high click-through rates (CTR).",
          "keywords": ["expressive faces", "emotions", "close-up", "CTR"]
        },
        {
          "name": "Create a Clear Focal Point",
          "instruction": "Design the composition to have **one main subject** and a clear visual hierarchy. Suggest using the **'rule of thirds'** for compositional guidance to avoid clutter and guide the viewer's eye.",
          "keywords": ["focal point", "rule of thirds", "hierarchy", "avoid clutter"]
        }
      ]
    },
    {
      "sectionTitle": "Text and Readability",
      "principles": [
        {
          "name": "Keep Text Minimal and Readable",
          "instruction": "If text is used, keep it short (ideally **3-5 words**), bold, and in a clean, sans-serif font. Ensure the size is large enough for small mobile screens. Use a **contrasting outline or background** to maximize readability.",
          "keywords": ["minimal text", "sans-serif", "bold", "readability", "outline"]
        }
      ]
    },
    {
      "sectionTitle": "Content Integrity",
      "principles": [
        {
          "name": "Avoid Misleading Content",
          "instruction": "The thumbnail must **accurately reflect the video's content**. Flag designs that are overly sensationalized or irrelevant to the core subject, as this ensures a good viewer retention rate.",
          "keywords": ["accurate reflection", "integrity", "viewer retention"]
        }
      ]
    },
    {
      "sectionTitle": "Testing",
      "instruction": "Highlight the importance of using app tools for A/B testing or performance analytics to determine the most effective thumbnail designs.",
      "keywords": ["tools", "testing", "performance"]
    }
  ]
}
